-- Additive content workspace: originals are preserved.
CREATE TABLE local_guide_catalog (id integer PRIMARY KEY CHECK(id=1), revision integer NOT NULL DEFAULT 0, entities jsonb NOT NULL CHECK(jsonb_typeof(entities)='array'));
CREATE TABLE local_guide_images (id text PRIMARY KEY, mime text NOT NULL CHECK(mime IN ('image/jpeg','image/png','image/webp')), bytes bytea NOT NULL CHECK(octet_length(bytes) BETWEEN 1 AND 8388608));
CREATE TABLE local_guide_history (id uuid PRIMARY KEY, revision integer UNIQUE NOT NULL, entities jsonb NOT NULL, actor text NOT NULL, created_at timestamptz NOT NULL DEFAULT NOW());
