INSERT INTO local_guide_images(id,mime,bytes) SELECT DISTINCT 'tour-'||encode(sha256(cover_image),'hex'),cover_image_mime_type,cover_image FROM agency_tours WHERE cover_image IS NOT NULL ON CONFLICT DO NOTHING;
WITH copied AS (
 SELECT jsonb_build_object('id','tour-'||slug,'kind','item','parentId','jeri-passeios','archived',false,
   'draft',data,'published',CASE WHEN enabled THEN data ELSE NULL END) AS entity
 FROM agency_tours t CROSS JOIN LATERAL (SELECT jsonb_build_object(
  'name',title,'summary',short_description,'description',description,'order',sort_order,
  'image',CASE WHEN cover_image IS NOT NULL THEN '/v1/content/guide/images/tour-'||encode(sha256(cover_image),'hex') ELSE '' END,
  'imagePosition',50,'filters','[]'::jsonb,'tags','[]'::jsonb,'featured',false,'badge',badge,'icon','tour',
  'address',coalesce(departure,''),'latitude',NULL,'longitude',NULL,'duration',coalesce(duration,''),'schedule',coalesce(schedule,''),
  'date','','cuisine','','source','','sourceUrl','','updatedOn','','priceLabel',price_label,'priceCents',price_cents,'priceSuffix',coalesce(price_suffix,''),
  'highlights',to_jsonb(highlights),'included',to_jsonb(included),'excluded',to_jsonb(excluded),
  'actions',CASE WHEN whatsapp_phone<>'' THEN jsonb_build_array(jsonb_build_object('id','reserve','type','whatsapp','label','Reservar pelo WhatsApp','primary',true,'enabled',true,'phone',replace(whatsapp_phone,'+',''),'message',whatsapp_message)) ELSE '[]'::jsonb END
 ) AS data) payload
)
UPDATE local_guide_catalog SET entities=entities||coalesce((SELECT jsonb_agg(entity) FROM copied),'[]'::jsonb) WHERE id=1;
INSERT INTO local_guide_history(id,revision,entities,actor) SELECT gen_random_uuid(),revision,entities,'Migração aditiva: passeios preservados' FROM local_guide_catalog;
